CREATE TABLE ai_prompt_config(id BIGINT NOT NULL,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,system_prompt TEXT NOT NULL,model_name VARCHAR(128) NOT NULL,temperature DECIMAL(3,2) NOT NULL DEFAULT 0.20,knowledge_scope TEXT NULL,sensitive_words TEXT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_ai_prompt_code(code),INDEX idx_ai_prompt_enabled(enabled));
CREATE TABLE ai_evaluation_case(id BIGINT NOT NULL,category VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,question TEXT NOT NULL,expected_evidence TEXT NOT NULL,forbidden_answer TEXT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_ai_eval_category_enabled(category,enabled));
CREATE TABLE ai_evaluation_run(id BIGINT NOT NULL,case_id BIGINT NOT NULL,prompt_config_id BIGINT NULL,answer MEDIUMTEXT NULL,citation_count INT UNSIGNED NOT NULL DEFAULT 0,passed BOOLEAN NOT NULL DEFAULT FALSE,score DECIMAL(5,2) NULL,failure_reason VARCHAR(1000) NULL,duration_ms BIGINT UNSIGNED NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_ai_eval_run_case_time(case_id,created_at));
